B.tO=new A.aV(984267,"MaterialIcons",!1)
B.Wl={"Maksimum Seviye":0,"K\xfcresel Bonus":1,"A\xe7\u0131l\u0131\u015f Seviyeleri":2}
B.Ve=new A.b3(B.Wl,["5","+%15 / Seviye","Sv 1: Temel, Sv 2: T\xf6re, Sv 3: Rafineri, Sv 4: \u0130klim, Sv 5: G\xf6ksel"],t.l)
B.SL=s(["Merkezdeki Ka\u011fan Ota\u011f\u0131 karosuna dokunun.","Alt men\xfcde gerekli Odun ve Ta\u015f miktar\u0131n\u0131 kontrol edin.","GEL\u0130\u015eT\u0130R butonuna basarak Ota\u011f seviyesini y\xfckseltin."],t.s)
B.Sv=s(["Tap on the central Khan's Tent hex.","Check the required Wood and Stone costs in the bottom sheet.","Tap UPGRADE to level up your tent."],t.s)
B.Sp=s(["Ota\u011f\u0131 y\xfckseltmeden \xf6nce ia\u015fe ve odun stoklar\u0131n\u0131z\u0131 dengeli tutun.","Her ota\u011f seviyesi yeni pazar kurlar\u0131 ve t\xf6re ferman\u0131 slotlar\u0131 sa\u011flar."],t.s)
B.Tl=s(["Keep your food and wood stockpiles balanced before upgrading.","Each tent level unlocks new market exchange rates and doctrine slots."],t.s)
